INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17232, 'koKR', 'Panel sterowania przesuwa się i obraca wokół własnej osi.', '', 0),
(17233, 'koKR', '<Naciśnij losowy przycisk.>', '<Naciśnij losowy przycisk.>', 0),
(17771, 'koKR', 'Pożywię się... twoją duszą.', '', 0),
(17772, 'koKR', 'Tyle... w tobie życia.', '', 0),
(17773, 'koKR', 'Nie... opieraj się.', '', 0),
(17774, 'koKR', 'Tak... moja moc... rośnie.', '', 0),
(17775, 'koKR', 'Więcej... muszę mieć więcej.', '', 0),
(17776, 'koKR', 'Z powrotem... w Pustkę.', '', 0),
(17777, 'koKR', 'Muszę się z tobą... pożegnać.', '', 0),
(17778, 'koKR', 'Na tym nasze drogi się rozchodzą.', '', 0),
(17779, 'koKR', 'To było... zabawne.', '', 0),
(17780, 'koKR', 'Nie zostaliśmy sobie należycie przedstawieni.', '', 0),
(17781, 'koKR', 'Epicka bitwa, jak ekscytująco!', '', 0),
(17782, 'koKR', 'Od dawna marzyłem o porządnej przygodzie!', '', 0),
(17783, 'koKR', 'Mam ci do pokazania tyle fascynujących rzeczy.', '', 0),
(17784, 'koKR', 'Cóż to? Wybaczcie, ale nie spodziewałem się gości. Jak widzicie, jesteśmy chwilowo dość zajęci. Ale nieważne. Jako gościnny gospodarz zajmę się wami... osobiście.', '', 0),
(21067, 'koKR', '%s przenika do Pustki...', '', 0);
